import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function designed to mimic specific ELA features.

    The function combines a skewed quadratic component, a linear component with pairwise interaction, and a localized Gaussian peak to shape the landscape.

    Formula:
        f(x) =  skewed_quadratic(x) + linear_with_interaction(x) + gaussian_peak(x)
    """

    def skewed_quadratic(x):
        """A skewed quadratic function."""
        return np.sum((x + 0.5)**2 + 0.1 * (x + 0.5)**3)

    def linear_with_interaction(x):
        """A linear function with pairwise interactions."""
        n = len(x)
        result = np.sum(x)
        for i in range(n):
            for j in range(i + 1, n):
                result += 0.1 * x[i] * x[j]
        return result

    def gaussian_peak(x):
        """A Gaussian peak centered at a specific location."""
        center = np.array([1.0, -0.5, 2.0])  # Example center in 3D
        amplitude = -3.0
        sigma = 0.5
        return amplitude * np.exp(-np.sum((x - center)**2) / (2 * sigma**2))

    return skewed_quadratic(x) + linear_with_interaction(x) + gaussian_peak(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A 3-dimensional synthetic benchmark function designed to mimic specific ELA features.

    The function combines a skewed polynomial component, a multiplicative interaction term, and a global sinusoidal modulation to shape the landscape.

    Formula:
        f(x) =  skewed_polynomial(x) + multiplicative_interaction(x) + sinusoidal_modulation(x)
    """

    def skewed_polynomial(x):
        """A skewed polynomial function."""
        return np.sum(x**2 + 0.2 * x**4 - 0.1 * x**3)

    def multiplicative_interaction(x):
        """A multiplicative interaction term."""
        return np.prod(np.sin(x)) * 0.5

    def sinusoidal_modulation(x):
        """A global sinusoidal modulation."""
        return np.sin(np.sum(x)) * 0.3

    return skewed_polynomial(x) + multiplicative_interaction(x) + sinusoidal_modulation(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A 3-dimensional synthetic benchmark function designed to mimic specific ELA features.

    The function combines trigonometric interactions, a polynomial scaling factor, and a Gaussian peak to shape the landscape.

    Formula:
        f(x) = trig_interaction(x) * poly_scale(x) + gaussian_peak(x)

    where:
        - trig_interaction(x) = cos(x[0] * x[1]) + sin(x[1] * x[2]) + cos(x[0] * x[2])
        - poly_scale(x) = 1 + 0.1 * x[0] + 0.05 * x[1]**2 + 0.02 * x[2]**3
        - gaussian_peak(x) = -0.5 * exp(-0.2 * ((x[0] - 0.5)**2 + (x[1] + 0.3)**2 + (x[2] - 1)**2))
    """

    def trig_interaction(x):
        """Trigonometric interaction term."""
        return np.cos(x[0] * x[1]) + np.sin(x[1] * x[2]) + np.cos(x[0] * x[2])

    def poly_scale(x):
        """Polynomial scaling factor."""
        return 1 + 0.1 * x[0] + 0.05 * x[1]**2 + 0.02 * x[2]**3

    def gaussian_peak(x):
        """Gaussian peak for modality."""
        return -0.5 * np.exp(-0.2 * ((x[0] - 0.5)**2 + (x[1] + 0.3)**2 + (x[2] - 1)**2))

    return trig_interaction(x) * poly_scale(x) + gaussian_peak(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function designed to mimic specific ELA features.

    The function combines a skewed exponential component, a ridge component, and a product of sine waves to shape the landscape.

    Formula:
        f(x) =  skewed_exp(x) + ridge(x) + sine_product(x)
    """

    def skewed_exp(x):
        """A skewed exponential function."""
        return np.sum(np.exp(x + 0.3) + 0.2 * (x + 0.3)**2)

    def ridge(x):
        """A ridge-like structure."""
        return np.sum(np.sin(2 * x))

    def sine_product(x):
        """Product of sine waves."""
        return np.prod(np.sin(x + 0.1))


    return skewed_exp(x) + ridge(x) + sine_product(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function designed to mimic specific ELA features.

    The function combines a skewed exponential component, a ridge component, and a product of sine waves to shape the landscape.

    Formula:
        f(x) =  skewed_exp(x) + ridge(x) + sine_product(x)
    """

    def skewed_exp(x):
        """A skewed exponential function with increased skewness."""
        return 0.1*np.sum(np.exp(2 * (x + 0.5)) + 0.5 * (x + 0.5)**2)

    def ridge(x):
        """A ridge-like structure with increased influence."""
        return 0.2*np.sum(np.sin(2 * x))

    def sine_product(x):
        """Product of sine waves with reduced amplitude."""
        return 0.05*np.prod(np.sin(x + 0.1))


    return skewed_exp(x) + ridge(x) + sine_product(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function designed to mimic specific ELA features.

    The function combines a skewed exponential component, a ridge component, and a product of sine waves to shape the landscape.

    Formula:
        f(x) =  skewed_exp(x) + ridge(x) + sine_product(x)
    """

    def skewed_exp(x):
        """A skewed exponential function."""
        return np.sum(np.exp(x + 0.5) + 0.5 * (x + 0.5)**2)

    def ridge(x):
        """A ridge-like structure."""
        return np.sum(np.sin(4 * x))

    def sine_product(x):
        """Product of sine waves."""
        return np.prod(np.sin(x + 0.2))


    return 1.5 * skewed_exp(x) + ridge(x) + 0.5 * sine_product(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function designed to mimic specific ELA features.

    This function combines multiplicative interactions, a skewed trigonometric component, and a penalty term.
    The function aims to create a non-separable landscape with controlled skewness and multimodality.

    Formula:
        f(x) = prod_interact(x) + skewed_trig(x) + penalty(x)
    """

    def prod_interact(x):
        """Multiplicative interactions between dimensions."""
        return np.prod(x)

    def skewed_trig(x):
        """Skewed trigonometric function."""
        skew = 0.1 * x[0]  # Skewness is influenced by the first dimension.

        return np.sum(np.sin((x + skew)))


    def penalty(x):
        """Penalty term to push solutions away from the boundaries."""
        penalty_strength = 0.01

        outside_bounds = np.logical_or(x < -5, x > 5)
        return penalty_strength * np.sum(x[outside_bounds]**2)


    return prod_interact(x) + skewed_trig(x) + penalty(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function designed to mimic specific ELA features.

    The function combines a skewed exponential component, a rotated quadratic bowl, and a sum of cosine waves to shape the landscape.

    Formula:
        f(x) =  skewed_exp(x) + rotated_quadratic(x) + cosine_sum(x)
    """

    def skewed_exp(x):
        """A skewed exponential function."""
        return np.sum(np.exp(x + 0.5) + 0.5 * (x + 0.5)**2)

    def rotated_quadratic(x):
      """A rotated quadratic bowl."""
      rotation_matrix = np.array([[0.707, -0.707, 0], [0.707, 0.707, 0], [0, 0, 1]])
      x_rotated = np.dot(x, rotation_matrix)
      return np.sum(x_rotated**2)

    def cosine_sum(x):
        """Sum of cosine waves."""
        return np.sum(np.cos(x * 3) * x) # Increased freq and added scaling

    return skewed_exp(x) + rotated_quadratic(x) + cosine_sum(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic 3-dimensional benchmark function.
    It combines a rotated elliptic function, a sum of cosines, and a linear term.

    f(x) = rotated_elliptic(x) + sum_of_cosines(x) + linear_term(x)

    rotated_elliptic(x) = sum(10**(i * (1-1/dim)) * (x_i)^2) where i = 0,...,dim-1
    sum_of_cosines(x) = sum(cos(2*pi*x_i))
    linear_term(x) = sum(c_i * x_i) where c_i are coefficients
    """
    dim = len(x)

    def rotated_elliptic(x: np.ndarray) -> float:
        return np.sum([(10**(i * (1-1/dim))) * (x[i]**2) for i in range(dim)])

    def sum_of_cosines(x: np.ndarray) -> float:
        return np.sum([np.cos(2 * np.pi * x[i]) for i in range(dim)])

    def linear_term(x: np.ndarray) -> float:
        c = np.array([0.1, -0.2, 0.3])
        return np.sum(c * x)


    return rotated_elliptic(x) * 0.0001 + sum_of_cosines(x) * 0.0005 + linear_term(x) + 0.5* np.exp(x[0]/5)
